oxy_webhelp_navlinks = {"sys_reqs_oracle_dbs-d39536e38309":{"topics":[{"title":"Direct NFS support","shortdesc":"<p class=\"shortdesc\">Rubrik CDM supports dNFS-enabled Oracle systems. Using dNFS-enabled Oracle databases     requires granting the discovery user specific privileges and applying the required Oracle     patches for your database version.<\/p>","href":"oracle\/dnfs_support.html","attributes":{"data-id":"dnfs_support"},"menu":{"hasChildren":false},"tocID":"dnfs_support-d39536e38320","topics":[]},{"title":"IBM GPFS support","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports Oracle databases running on IBM GPFS, but these         databases have specific limitations and recovery parameter requirements to review before         configuring protection.<\/p>","href":"oracle\/ibm_gpfs_support.html","attributes":{"data-id":"ibm_gpfs_support"},"menu":{"hasChildren":false},"tocID":"ibm_gpfs_support-d39536e38331","topics":[]},{"title":"Oracle ACFS support","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports Oracle databases running on Oracle ACFS, but these         databases have specific limitations and recovery parameter requirements that you must         consider before configuring protection.<\/p>","href":"oracle\/oracle_acfs_support.html","attributes":{"data-id":"oracle_acfs_support"},"menu":{"hasChildren":false},"tocID":"oracle_acfs_support-d39536e38344","topics":[]}]}};